// ===========================================================================
//  CẤU HÌNH - anh chỉnh ở đây
// ===========================================================================
// Danh sách mã cổ phiếu theo dõi (thêm/bớt tuỳ ý)
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

// Ngưỡng cảnh báo
const VOL_SPIKE   = 2.0;   // Khối lượng hôm nay >= 2x trung bình 20 phiên
const PRICE_MOVE  = 3.0;   // |Thay đổi giá| >= 3% so với phiên trước
const LOOKBACK    = 20;    // Số phiên tính trung bình khối lượng
// ===========================================================================

const to = Math.floor(Date.now() / 1000);
const alerts = [];

for (const ticker of WATCHLIST) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://apipubaws.tcbs.com.vn/stock-insight/v1/stock/bars-long-term',
      qs: { ticker, type: 'stock', resolution: 'D', to, countBack: 30 },
      json: true,
    });

    const bars = (res && res.data) || [];
    if (bars.length < 5) continue;

    const today = bars[bars.length - 1];
    const prev  = bars[bars.length - 2];

    // Trung bình khối lượng các phiên trước (loại phiên hôm nay)
    const hist     = bars.slice(0, bars.length - 1);
    const lookback = hist.slice(-LOOKBACK);
    const avgVol   = lookback.reduce((s, b) => s + (b.volume || 0), 0) / (lookback.length || 1);

    const volRatio = avgVol ? today.volume / avgVol : 0;
    const pct      = prev.close ? ((today.close - prev.close) / prev.close) * 100 : 0;

    const reasons = [];
    if (volRatio >= VOL_SPIKE)         reasons.push(`📈 KL đột biến x${volRatio.toFixed(1)}`);
    if (Math.abs(pct) >= PRICE_MOVE)   reasons.push(`${pct >= 0 ? '🟢' : '🔴'} Giá ${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%`);

    if (reasons.length) {
      alerts.push({ ticker, close: today.close, pct, volRatio, reasons });
    }
  } catch (e) {
    // Bỏ qua mã lỗi, không làm hỏng cả luồng
    continue;
  }
}

if (!alerts.length) {
  return [{ json: { hasAlerts: false, count: 0 } }];
}

// Giá TCBS trả về theo đơn vị nghìn đồng -> nhân 1000 để hiển thị
const lines = alerts
  .sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct))
  .map(a => `*${a.ticker}* — ${(a.close * 1000).toLocaleString('vi-VN')}đ\n   ${a.reasons.join('  |  ')}`);

const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const message = `🔔 *CẢNH BÁO CỔ PHIẾU BẤT THƯỜNG*\n_${now}_\n\n${lines.join('\n\n')}\n\n_Nguồn: TCBS · ${alerts.length} mã_`;

return [{ json: { hasAlerts: true, message, count: alerts.length } }];
